diff --git a/db/migrations/009_allow_stage_retention.sql b/db/migrations/009_allow_stage_retention.sql
new file mode 100644
--- /dev/null
+++ b/db/migrations/009_allow_stage_retention.sql
@@ -0,0 +1,11 @@
+ALTER TABLE stage_retention RENAME TO previous_values;
+CREATE TABLE stage_retention (
+  project TEXT NOT NULL,
+  stage_code INTEGER NOT NULL,
+  days INTEGER NOT NULL CONSTRAINT retention_days CHECK (days BETWEEN 1 AND (CASE stage_code WHEN 3 THEN 3650 WHEN 4 THEN 30 ELSE 365 END)),
+  updated_by TEXT NOT NULL,
+  updated_at INTEGER NOT NULL,
+  PRIMARY KEY (project, stage_code)
+);
+INSERT INTO stage_retention SELECT * FROM previous_values;
+DROP TABLE previous_values;
