+
+  /** Place a job that is still at its first revision in its starting stage. */
+  startIn(id: string, stage: Stage): Job {
+    if (this.require(id).revision !== 1) conflict("job has already changed");
+    this.db.query("UPDATE jobs SET stage = ? WHERE id = ? AND revision = 1").run(stage, id);
     return this.require(id);
   }

